import 'dart:io';import 'package:flutter/material.dart';import '../../../core/utils/validators.dart';import '../../../shared/widgets/app_text_field.dart';import 'category_selector.dart';import 'photo_picker.dart';class IncidentForm extends StatefulWidget{const IncidentForm({super.key,required this.formKey,required this.titleController,required this.descriptionController,required this.locationController,required this.onCategoryChanged,required this.onPhotoChanged});final GlobalKey<FormState> formKey;final TextEditingController titleController,descriptionController,locationController;final ValueChanged<String> onCategoryChanged;final ValueChanged<File?> onPhotoChanged;@override State<IncidentForm> createState()=>_IncidentFormState();}class _IncidentFormState extends State<IncidentForm>{String category='Broken Facilities';@override Widget build(BuildContext context)=>Form(key:widget.formKey,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[AppTextField(controller:widget.titleController,label:'Short title',validator:(v)=>Validators.required(v,label:'Title')),const SizedBox(height:12),CategorySelector(value:category,onChanged:(v){setState(()=>category=v);widget.onCategoryChanged(v);}),const SizedBox(height:12),AppTextField(controller:widget.descriptionController,label:'Describe the issue',maxLines:4,validator:(v){final e=Validators.required(v,label:'Description');if(e!=null)return e;return v!.trim().length<10?'Add at least 10 characters.':null;}),const SizedBox(height:12),AppTextField(controller:widget.locationController,label:'Campus location / building',validator:(v)=>Validators.required(v,label:'Location')),const SizedBox(height:12),PhotoPicker(onChanged:widget.onPhotoChanged)]));}
